$ErrorActionPreference = 'Stop'
$stageRoot = [IO.Path]::GetFullPath('C:\public\project-hyle\hyle\.scratch\multisequence-batch-20261021')
$stagePrefix = $stageRoot + '\'
$planPath = Join-Path $stageRoot 'cleanup-plan.json'
$receiptPath = 'C:\public\project-hyle\hyle\docs\evidence\correctness\paged-frame-reframe-2026-10-21.cleanup.json'
if (Test-Path -LiteralPath $receiptPath) { throw 'Cleanup already has a receipt; do not repeat.' }
function Assert-Identity($row) {
    $item = Get-Item -LiteralPath $row.path
    if ($item.PSIsContainer -or $item.Length -ne $row.bytes) { throw "Wrong file: $($row.path)" }
    if ((Get-FileHash -LiteralPath $row.path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $row.sha256) { throw "Changed file: $($row.path)" }
}
$manifest = 'C:\public\project-hyle\hyle\docs\evidence\correctness\paged-frame-reframe-2026-10-21.json'
$archive = 'C:\public\project-hyle\hyle\docs\evidence\correctness\paged-frame-reframe-2026-10-21.zip'
Assert-Identity @{path=$manifest;bytes=15995;sha256='64e7b61b6617724a5bcce649eb329bb6a7dc8c086220f2721156d8e610389de4'}
Assert-Identity @{path=$archive;bytes=843617;sha256='5ea2d39f21420f6707f4375b58168619575ea91535f49e8caf8e703268345e30'}
$plan = Get-Content -LiteralPath $planPath -Raw -Encoding utf8 | ConvertFrom-Json
if ([IO.Path]::GetFullPath($plan.allowed_root) -ne $stageRoot -or $plan.target_count -ne 28) { throw 'Unexpected cleanup scope.' }
$running = @(Get-CimInstance Win32_Process | Where-Object { $_.ExecutablePath -and $_.ExecutablePath.StartsWith($stagePrefix, [StringComparison]::OrdinalIgnoreCase) })
if ($running.Count) { throw 'A process from this stage is running.' }
$seen = [Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
foreach ($row in $plan.targets) {
    $resolved = [IO.Path]::GetFullPath($row.path)
    if (-not $resolved.StartsWith($stagePrefix, [StringComparison]::OrdinalIgnoreCase) -or -not $seen.Add($resolved)) { throw "Outside/duplicate: $resolved" }
    if ([IO.Path]::GetExtension($resolved) -notin @('.exe','.map','.lib','.exp')) { throw "Unexpected file type: $resolved" }
    $at = Get-Item -LiteralPath $resolved
    while ($null -ne $at) {
        if (($at.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { throw "Reparse path: $resolved" }
        if ($at.FullName -eq $stageRoot) { break }
        $at = if ($at.PSIsContainer) { $at.Parent } else { $at.Directory }
    }
    Assert-Identity $row
}
foreach ($row in $plan.targets) {
    Remove-Item -LiteralPath $row.path -Force
    if (Test-Path -LiteralPath $row.path) { throw "Target remains: $($row.path)" }
}
$result = [ordered]@{status='completed';time_utc=[DateTime]::UtcNow.ToString('o');deleted_files=$plan.target_count;deleted_bytes=$plan.total_bytes;targets=$plan.targets;recursive_delete=$false;kept='All objects, SDK/dependency caches, source, commands, logs, runtime DLL hardlinks, and current Qwen images';plan_sha256=(Get-FileHash -LiteralPath $planPath -Algorithm SHA256).Hash.ToLowerInvariant();script_sha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();script_text=(Get-Content -LiteralPath $PSCommandPath -Raw -Encoding utf8)}
$result | ConvertTo-Json -Depth 10 | Set-Content -LiteralPath $receiptPath -Encoding utf8
Write-Output "Removed $($result.deleted_files) exact files, $($result.deleted_bytes) bytes."
